INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT148-S3-Q4$batch10$, 148, 3, 4, $batch10$Main Conclusion$batch10$, $batch10$Electric stovetop burners would cause fewer fires if their highest temperature were limited to 350°C (662°F), which provides more than enough heat for efficient and effective cooking. The lowest temperature at which cooking oil and most common fibers ignite is 387°C, and electric burners on high go well above 700°C.$batch10$, $batch10$Which one of the following most accurately expresses the conclusion drawn in the argument?$batch10$, $batch10$A$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=148 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT148-S3-Q4$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$Electric stovetop burners would cause fewer fires if their highest temperature were limited to 350°C.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$A maximum temperature of 350°C provides more than enough heat for efficient and effective cooking.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$The lowest ignition temperature for cooking oil and most common fibers is 387°C.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$Electric burners on high go well above 700°C.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$Electric stovetop burners cause fires because they go well above 700°C when set on high.$batch10$, $batch10$Not Stated$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Electric burners would cause fewer fires if their highest temperature were limited to 350°C.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$350°C is plenty for cooking. Cooking oil and most fibers ignite at 387°C at the lowest, and burners on high go well above 700°C.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The first sentence makes the claim. The rest explains why a 350°C limit would prevent fires: it is below the ignition point, yet hot enough to cook.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Limiting burners to 350°C would mean fewer fires.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the first sentence, which the other facts support.$batch10$), ($batch10$B$batch10$, $batch10$This shows the limit wouldn't hurt cooking. It supports the proposal.$batch10$), ($batch10$C$batch10$, $batch10$This is the ignition threshold the limit stays below.$batch10$), ($batch10$D$batch10$, $batch10$This shows current burners get hot enough to start fires.$batch10$), ($batch10$E$batch10$, $batch10$The argument doesn't claim to explain why fires start. It says a limit would reduce them.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT148-S3-Q4$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
